-- Solo lectura. Repetir tras reejecución, sin asumir tablas vacías.
SELECT 'tablas_c11' control,3-COUNT(*) errores FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND ENGINE='InnoDB' AND TABLE_NAME IN ('cont_regularizacion_politicas','cont_regularizacion_solicitudes','cont_regularizacion_decisiones');
SELECT 'columnas_c11' control,43-COUNT(*) errores FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME='cont_regularizacion_politicas' AND COLUMN_NAME IN ('empresa_id','entidad_id','ejercicio_id','codigo','version','estado','contrato_json','huella_politica','huella_condiciones','preparador_id','revisor_id','resolutor_id','clave_idempotencia','huella_solicitud','creado_por','creado_en')) OR (TABLE_NAME='cont_regularizacion_solicitudes' AND COLUMN_NAME IN ('id','empresa_id','entidad_id','ejercicio_id','politica_codigo','politica_version','borrador_version','huella_condiciones','justificacion','diagnostico_json','clave_idempotencia','huella_solicitud','creado_por','creado_en')) OR (TABLE_NAME='cont_regularizacion_decisiones' AND COLUMN_NAME IN ('empresa_id','entidad_id','ejercicio_id','solicitud_id','version','accion','estado_anterior','justificacion','huella_observada','clave_idempotencia','huella_solicitud','creado_por','creado_en')));
SELECT 'restricciones_c11' control,12-COUNT(*) errores FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN ('cont_regularizacion_politicas','cont_regularizacion_solicitudes','cont_regularizacion_decisiones') AND CONSTRAINT_NAME IN ('fk_c11_politica_ejercicio','fk_c11_politica_preparador','fk_c11_politica_revisor','fk_c11_politica_resolutor','ck_c11_politica','fk_c11_solicitud_politica','fk_c11_solicitud_borrador','fk_c11_solicitud_usuario','ck_c11_solicitud','fk_c11_decision_solicitud','fk_c11_decision_usuario','ck_c11_decision');
SELECT 'triggers_c11' control,6-COUNT(*) errores FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND ACTION_TIMING='BEFORE' AND ACTION_STATEMENT LIKE '%SIGNAL SQLSTATE%45000%' AND ((EVENT_OBJECT_TABLE='cont_regularizacion_politicas' AND ((TRIGGER_NAME='c11_politica_no_update' AND EVENT_MANIPULATION='UPDATE') OR (TRIGGER_NAME='c11_politica_no_delete' AND EVENT_MANIPULATION='DELETE'))) OR (EVENT_OBJECT_TABLE='cont_regularizacion_solicitudes' AND ((TRIGGER_NAME='c11_solicitud_no_update' AND EVENT_MANIPULATION='UPDATE') OR (TRIGGER_NAME='c11_solicitud_no_delete' AND EVENT_MANIPULATION='DELETE'))) OR (EVENT_OBJECT_TABLE='cont_regularizacion_decisiones' AND ((TRIGGER_NAME='c11_decision_no_update' AND EVENT_MANIPULATION='UPDATE') OR (TRIGGER_NAME='c11_decision_no_delete' AND EVENT_MANIPULATION='DELETE'))));
SELECT 'unicidad_c11' control,7-COUNT(*) errores FROM (SELECT TABLE_NAME t,INDEX_NAME n,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND NON_UNIQUE=0 AND TABLE_NAME IN ('cont_regularizacion_politicas','cont_regularizacion_solicitudes','cont_regularizacion_decisiones') GROUP BY TABLE_NAME,INDEX_NAME) i WHERE (t='cont_regularizacion_politicas' AND ((n='PRIMARY' AND cols='empresa_id,entidad_id,ejercicio_id,codigo,version') OR (n='uq_c11_politica_clave' AND cols='empresa_id,entidad_id,clave_idempotencia'))) OR (t='cont_regularizacion_solicitudes' AND ((n='uq_c11_solicitud_ambito' AND cols='empresa_id,entidad_id,ejercicio_id,id') OR (n='uq_c11_solicitud_clave' AND cols='empresa_id,entidad_id,clave_idempotencia') OR (n='uq_c11_solicitud_fuente' AND cols='empresa_id,entidad_id,ejercicio_id,borrador_version'))) OR (t='cont_regularizacion_decisiones' AND ((n='PRIMARY' AND cols='empresa_id,entidad_id,ejercicio_id,solicitud_id,version') OR (n='uq_c11_decision_clave' AND cols='empresa_id,entidad_id,clave_idempotencia')));
